//! Native resource packer.
//!
//! Reads the raw `manifest.json` (generated by `tools/make_manifest.py`) and the
//! original install files it names, builds a [`ResourcePack`], serializes it,
//! and writes a standard ZIP archive containing:
//!
//! ```text
//! bundle.bin   bincode(ResourcePack), DEFLATE
//! pack.json    human-readable index, STORE
//! ```
//!
//! This is a separate native compilation target and is never linked into the
//! wasm module. Usage:
//!
//! ```text
//! cargo run --release --example pack -- \
//!     --base .. --manifest www/manifest.raw.json --out www/openkonung.pack.zip
//! ```

use std::collections::BTreeMap;
use std::path::{Path, PathBuf};

use openkonung::resource_pack::{
    IdBlob, MusicBlob, NamedBlob, ResourcePack, VideoBlob, PACK_ENTRY, PACK_FORMAT, PACK_INDEX,
    PACK_MANIFEST,
};
use serde_json::Value;

fn main() {
    if let Err(e) = run() {
        eprintln!("pack: {e}");
        std::process::exit(1);
    }
}

struct Args {
    base: PathBuf,
    manifest: PathBuf,
    out: PathBuf,
}

fn parse_args() -> Result<Args, String> {
    let mut base = None;
    let mut manifest = None;
    let mut out = None;
    let mut it = std::env::args().skip(1);
    while let Some(arg) = it.next() {
        match arg.as_str() {
            "--base" => base = it.next(),
            "--manifest" => manifest = it.next(),
            "--out" => out = it.next(),
            "-h" | "--help" => {
                println!(
                    "usage: pack --base <install-dir> --manifest <raw-manifest.json> --out <archive.zip>"
                );
                std::process::exit(0);
            }
            other => return Err(format!("unknown argument '{other}'")),
        }
    }
    let base = base.ok_or("missing --base")?;
    let manifest = manifest.ok_or("missing --manifest")?;
    let out = out.ok_or("missing --out")?;
    Ok(Args {
        base: PathBuf::from(base),
        manifest: PathBuf::from(manifest),
        out: PathBuf::from(out),
    })
}

fn run() -> Result<(), String> {
    let args = parse_args()?;
    let started = std::time::Instant::now();

    let manifest_text = std::fs::read_to_string(&args.manifest)
        .map_err(|e| format!("read {}: {e}", args.manifest.display()))?;
    let manifest: Value =
        serde_json::from_str(&manifest_text).map_err(|e| format!("parse manifest: {e}"))?;

    let base = &args.base;
    let mut resources = Vec::new();
    let mut source = BTreeMap::new();

    let res = manifest
        .get("resources")
        .and_then(|v| v.as_object())
        .ok_or("manifest has no 'resources' object")?;

    let core = [
        (0u32, "game"),
        (1, "graph"),
        (2, "objects"),
        (3, "exe"),
        (4, "names"),
    ];
    for (kind, key) in core {
        if let Some(rel) = res
            .get(key)
            .and_then(|v| v.as_str())
            .filter(|s| !s.is_empty())
        {
            resources.push(NamedBlob {
                name: rel.to_string(),
                kind,
                bytes: read_blob(base, rel)?,
            });
            source.insert(key.to_string(), rel.to_string());
        }
    }

    // Menu-image families, both original resolutions. SAVE is optional; the
    // frontend accepts a missing save screen.
    for (width, first_kind) in [("640", 5u32), ("800", 6u32)] {
        let Some(entry) = manifest.get("menu").and_then(|m| m.get(width)) else {
            continue;
        };
        for (key, kind) in [
            ("menu", first_kind),
            ("newh", first_kind + 2),
            ("save", first_kind + 4),
        ] {
            if let Some(rel) = entry
                .get(key)
                .and_then(|v| v.as_str())
                .filter(|s| !s.is_empty())
            {
                resources.push(NamedBlob {
                    name: rel.to_string(),
                    kind,
                    bytes: read_blob(base, rel)?,
                });
                source.insert(format!("menu{width}_{key}"), rel.to_string());
            }
        }
    }

    // INTR interface archives, quest database and sound archive.
    for (width, kind) in [("640", 11u32), ("800", 12u32)] {
        if let Some(rel) = manifest
            .get("intr")
            .and_then(|m| m.get(width))
            .and_then(|v| v.as_str())
            .filter(|s| !s.is_empty())
        {
            resources.push(NamedBlob {
                name: rel.to_string(),
                kind,
                bytes: read_blob(base, rel)?,
            });
            source.insert(format!("intr{width}"), rel.to_string());
        }
    }
    for (key, kind) in [
        ("quest", 13u32),
        ("sounds", 14),
        ("flames", 15),
        ("lights", 16),
    ] {
        if let Some(rel) = manifest
            .get(key)
            .and_then(|v| v.as_str())
            .filter(|s| !s.is_empty())
        {
            resources.push(NamedBlob {
                name: rel.to_string(),
                kind,
                bytes: read_blob(base, rel)?,
            });
            source.insert(key.to_string(), rel.to_string());
        }
    }

    let mut profiles = Vec::new();
    if let Some(list) = manifest.get("profiles").and_then(|v| v.as_array()) {
        for item in list {
            let Some(rel) = item.as_str() else { continue };
            let id = id_from_name(rel).ok_or_else(|| format!("bad profile name '{rel}'"))?;
            profiles.push(IdBlob {
                id,
                name: rel.to_string(),
                bytes: read_blob(base, rel)?,
            });
        }
    }
    profiles.sort_by_key(|p| p.id);

    let mut konungs = Vec::new();
    if let Some(list) = manifest.get("konungs").and_then(|v| v.as_array()) {
        for item in list {
            let id = item
                .get("id")
                .and_then(|v| v.as_u64())
                .ok_or("Konung entry without numeric id")? as u32;
            let rel = item
                .get("file")
                .and_then(|v| v.as_str())
                .ok_or("Konung entry without file")?;
            konungs.push(IdBlob {
                id,
                name: rel.to_string(),
                bytes: read_blob(base, rel)?,
            });
        }
    }
    konungs.sort_by_key(|k| k.id);

    let mut light_maps = Vec::new();
    if let Some(list) = manifest.get("light_maps").and_then(|v| v.as_array()) {
        for item in list {
            let id = item
                .get("id")
                .and_then(|v| v.as_u64())
                .ok_or("light entry without numeric id")? as u32;
            let rel = item
                .get("file")
                .and_then(|v| v.as_str())
                .ok_or("light entry without file")?;
            light_maps.push(IdBlob {
                id,
                name: rel.to_string(),
                bytes: read_blob(base, rel)?,
            });
        }
    }
    light_maps.sort_by_key(|k| k.id);

    let mut music = Vec::new();
    if let Some(list) = manifest.get("music").and_then(|v| v.as_array()) {
        for item in list {
            let Some(rel) = item.as_str() else { continue };
            music.push(MusicBlob {
                name: rel.to_string(),
                bytes: read_blob(base, rel)?,
            });
        }
    }

    // Browser-playable MP4s live beside the manifest (`www/video/*.mp4`).
    // They are embedded so a pack-only deployment can play every movie and the
    // per-file manifest URLs remain the fallback for `?nopack=1`.
    let mut videos = Vec::new();
    if let Some(map) = manifest.get("videos").and_then(|v| v.as_object()) {
        let www = args
            .manifest
            .parent()
            .ok_or("manifest path has no parent directory")?;
        let mut entries: Vec<_> = map.iter().collect();
        entries.sort_by(|a, b| a.0.cmp(b.0));
        for (name, item) in entries {
            let rel = item
                .as_str()
                .or_else(|| item.get("file").and_then(|v| v.as_str()))
                .filter(|s| !s.is_empty());
            let Some(rel) = rel else { continue };
            videos.push(VideoBlob {
                name: name.to_string(),
                bytes: read_blob(www, rel)?,
            });
        }
    }
    videos.sort_by(|a, b| a.name.cmp(&b.name));

    let mut pack = ResourcePack {
        format: PACK_FORMAT,
        build: String::new(),
        source,
        resources,
        profiles,
        konungs,
        light_maps,
        music,
        videos,
    };
    pack.build = pack.compute_build();
    pack.validate().map_err(|e| e.to_string())?;

    let bundle = pack.to_bytes().map_err(|e| e.to_string())?;
    let index = serde_json::json!({
        "format": pack.format,
        "build": pack.build,
        "entry": PACK_ENTRY,
        "resources": pack.resources.iter().map(|r| serde_json::json!({
            "name": r.name, "kind": r.kind, "bytes": r.bytes.len()
        })).collect::<Vec<_>>(),
        "profiles": pack.profiles.iter().map(|p| serde_json::json!({
            "id": p.id, "name": p.name, "bytes": p.bytes.len()
        })).collect::<Vec<_>>(),
        "konungs": pack.konungs.iter().map(|k| serde_json::json!({
            "id": k.id, "name": k.name, "bytes": k.bytes.len()
        })).collect::<Vec<_>>(),
        "lights": pack.light_maps.iter().map(|k| serde_json::json!({
            "id": k.id, "name": k.name, "bytes": k.bytes.len()
        })).collect::<Vec<_>>(),
        "music": pack.music.iter().map(|m| serde_json::json!({
            "name": m.name, "bytes": m.bytes.len()
        })).collect::<Vec<_>>(),
        "videos": pack.videos.iter().map(|v| serde_json::json!({
            "name": v.name, "bytes": v.bytes.len()
        })).collect::<Vec<_>>(),
    });
    let index_bytes =
        serde_json::to_vec_pretty(&index).map_err(|e| format!("serialize index: {e}"))?;

    if let Some(parent) = args.out.parent() {
        if !parent.as_os_str().is_empty() {
            std::fs::create_dir_all(parent)
                .map_err(|e| format!("create {}: {e}", parent.display()))?;
        }
    }
    let written = openkonung::resource_pack::zip::write_archive_file(
        &[
            (PACK_ENTRY, bundle.as_slice(), true),
            (PACK_INDEX, index_bytes.as_slice(), false),
            (PACK_MANIFEST, manifest_text.as_bytes(), false),
        ],
        &args.out,
    )
    .map_err(|e| e.to_string())?;

    let raw: usize = pack
        .resources
        .iter()
        .map(|r| r.bytes.len())
        .chain(pack.profiles.iter().map(|p| p.bytes.len()))
        .chain(pack.konungs.iter().map(|k| k.bytes.len()))
        .chain(pack.light_maps.iter().map(|k| k.bytes.len()))
        .chain(pack.music.iter().map(|m| m.bytes.len()))
        .chain(pack.videos.iter().map(|v| v.bytes.len()))
        .sum();

    println!(
        "pack: {} resources, {} profiles, {} maps, {} light maps, {} music tracks, {} videos, build {}",
        pack.resources.len(),
        pack.profiles.len(),
        pack.konungs.len(),
        pack.light_maps.len(),
        pack.music.len(),
        pack.videos.len(),
        pack.build
    );
    println!(
        "pack: raw {:.1} MiB -> {} bytes ({:.1} MiB) in {:.1?} -> {}",
        raw as f64 / (1024.0 * 1024.0),
        written,
        written as f64 / (1024.0 * 1024.0),
        started.elapsed(),
        args.out.display()
    );
    Ok(())
}

fn read_blob(base: &Path, rel: &str) -> Result<Vec<u8>, String> {
    let path = base.join(rel);
    let bytes = std::fs::read(&path).map_err(|e| format!("read {}: {e}", path.display()))?;
    if bytes.is_empty() {
        return Err(format!("{} is empty", path.display()));
    }
    Ok(bytes)
}

fn id_from_name(name: &str) -> Option<u32> {
    let digits: String = name.chars().filter(|c| c.is_ascii_digit()).collect();
    digits.parse().ok()
}
